const sqlite3 = require('sqlite3').verbose();
const path = require('path');
const fs = require('fs');

const DB_PATH = path.join(__dirname, 'gridforge.sqlite3');

class Database {
  constructor() {
    this.db = null;
  }

  async init() {
    return new Promise((resolve, reject) => {
      this.db = new sqlite3.Database(DB_PATH, (err) => {
        if (err) reject(err);
        else this.setupSchema().then(resolve).catch(reject);
      });
    });
  }

  async setupSchema() {
    return Promise.all([
      this.run(`
        CREATE TABLE IF NOT EXISTS workbooks (
          id TEXT PRIMARY KEY,
          title TEXT NOT NULL,
          current_revision INTEGER NOT NULL DEFAULT 0
        )
      `),
      this.run(`
        CREATE TABLE IF NOT EXISTS sheets (
          id TEXT NOT NULL,
          workbook_id TEXT NOT NULL,
          name TEXT NOT NULL,
          PRIMARY KEY (workbook_id, id),
          FOREIGN KEY (workbook_id) REFERENCES workbooks(id)
        )
      `),
      this.run(`
        CREATE TABLE IF NOT EXISTS revisions (
          id INTEGER PRIMARY KEY AUTOINCREMENT,
          workbook_id TEXT NOT NULL,
          revision INTEGER NOT NULL,
          snapshot TEXT NOT NULL,
          created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
          UNIQUE(workbook_id, revision),
          FOREIGN KEY (workbook_id) REFERENCES workbooks(id)
        )
      `),
      this.run(`
        CREATE TABLE IF NOT EXISTS cell_changes (
          id INTEGER PRIMARY KEY AUTOINCREMENT,
          workbook_id TEXT NOT NULL,
          sheet_id TEXT NOT NULL,
          cell_address TEXT NOT NULL,
          revision INTEGER NOT NULL,
          previous_value TEXT,
          new_value TEXT NOT NULL,
          user_id TEXT NOT NULL,
          changed_at DATETIME DEFAULT CURRENT_TIMESTAMP,
          FOREIGN KEY (workbook_id) REFERENCES workbooks(id)
        )
      `),
      this.run(`
        CREATE TABLE IF NOT EXISTS sessions (
          session_id TEXT PRIMARY KEY,
          workbook_id TEXT NOT NULL,
          user_id TEXT NOT NULL,
          created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
          last_activity DATETIME DEFAULT CURRENT_TIMESTAMP
        )
      `)
    ]);
  }

  run(sql, params = []) {
    return new Promise((resolve, reject) => {
      this.db.run(sql, params, function(err) {
        if (err) reject(err);
        else resolve({ lastID: this.lastID, changes: this.changes });
      });
    });
  }

  get(sql, params = []) {
    return new Promise((resolve, reject) => {
      this.db.get(sql, params, (err, row) => {
        if (err) reject(err);
        else resolve(row);
      });
    });
  }

  all(sql, params = []) {
    return new Promise((resolve, reject) => {
      this.db.all(sql, params, (err, rows) => {
        if (err) reject(err);
        else resolve(rows || []);
      });
    });
  }

  async loadSeedIfNeeded() {
    const seedPath = path.join(__dirname, '../assets/workbook_seed.json');
    const seed = JSON.parse(fs.readFileSync(seedPath, 'utf8'));

    const existing = await this.get('SELECT id FROM workbooks WHERE id = ?', [seed.workbook.id]);
    if (existing) return;

    const workbook = seed.workbook;
    await this.run('INSERT INTO workbooks (id, title, current_revision) VALUES (?, ?, ?)', 
      [workbook.id, workbook.title, 0]);

    for (const sheet of workbook.sheets) {
      await this.run('INSERT INTO sheets (workbook_id, id, name) VALUES (?, ?, ?)',
        [workbook.id, sheet.id, sheet.name]);
    }

    const snapshot = {
      workbook: {
        id: workbook.id,
        title: workbook.title,
        sheets: workbook.sheets.map(s => ({ id: s.id, name: s.name }))
      },
      sheets: workbook.sheets.map(s => ({
        id: s.id,
        name: s.name,
        cells: s.cells || {}
      }))
    };

    await this.run(
      'INSERT INTO revisions (workbook_id, revision, snapshot) VALUES (?, ?, ?)',
      [workbook.id, 0, JSON.stringify(snapshot)]
    );
  }

  async saveRevision(workbookId, snapshot) {
    const workbook = await this.get('SELECT current_revision FROM workbooks WHERE id = ?', [workbookId]);
    if (!workbook) throw new Error('Workbook not found');

    const newRevision = workbook.current_revision + 1;
    await this.run(
      'INSERT INTO revisions (workbook_id, revision, snapshot) VALUES (?, ?, ?)',
      [workbookId, newRevision, JSON.stringify(snapshot)]
    );
    await this.run('UPDATE workbooks SET current_revision = ? WHERE id = ?', [newRevision, workbookId]);
    return newRevision;
  }

  async getRevision(workbookId, revision = null) {
    let query = 'SELECT * FROM revisions WHERE workbook_id = ?';
    let params = [workbookId];
    if (revision !== null) {
      query += ' AND revision = ?';
      params.push(revision);
    } else {
      query += ' ORDER BY revision DESC LIMIT 1';
    }
    const row = await this.get(query, params);
    return row ? JSON.parse(row.snapshot) : null;
  }

  async getRevisions(workbookId, limit = 50) {
    const rows = await this.all(
      'SELECT revision, created_at FROM revisions WHERE workbook_id = ? ORDER BY revision DESC LIMIT ?',
      [workbookId, limit]
    );
    return rows;
  }

  async getCellHistory(workbookId, sheetId, cellAddress, limit = 50) {
    return this.all(
      `SELECT cell_address, previous_value, new_value, user_id, changed_at 
       FROM cell_changes 
       WHERE workbook_id = ? AND sheet_id = ? AND cell_address = ?
       ORDER BY changed_at DESC LIMIT ?`,
      [workbookId, sheetId, cellAddress, limit]
    );
  }

  async recordCellChange(workbookId, sheetId, cellAddress, revision, previousValue, newValue, userId) {
    await this.run(
      `INSERT INTO cell_changes (workbook_id, sheet_id, cell_address, revision, previous_value, new_value, user_id)
       VALUES (?, ?, ?, ?, ?, ?, ?)`,
      [workbookId, sheetId, cellAddress, revision, previousValue, newValue, userId]
    );
  }

  async getWorkbook(workbookId) {
    return this.get('SELECT * FROM workbooks WHERE id = ?', [workbookId]);
  }

  async getSheets(workbookId) {
    return this.all('SELECT * FROM sheets WHERE workbook_id = ?', [workbookId]);
  }

  close() {
    return new Promise((resolve, reject) => {
      if (this.db) {
        this.db.close((err) => {
          if (err) reject(err);
          else resolve();
        });
      } else resolve();
    });
  }
}

module.exports = Database;

class FormulaCalculator {
  constructor(cells) {
    this.cells = cells || {};
    this.computing = new Set();
  }

  setCells(cells) {
    this.cells = cells || {};
  }

  isFormula(value) {
    return typeof value === 'string' && value.startsWith('=');
  }

  calculate(value) {
    if (!this.isFormula(value)) {
      const num = parseFloat(value);
      return isNaN(num) ? value : num;
    }

    const formula = value.substring(1).trim();
    try {
      return this.evaluateExpression(formula);
    } catch (e) {
      return '#ERROR: ' + e.message;
    }
  }

  getCellValue(address) {
    const value = this.cells[address];
    if (value === undefined || value === '') return 0;
    if (this.isFormula(value)) return this.calculate(value);
    const num = parseFloat(value);
    return isNaN(num) ? 0 : num;
  }

  evaluateExpression(expr) {
    expr = expr.trim();

    if (this.computing.has(expr)) {
      throw new Error('Circular reference');
    }

    this.computing.add(expr);
    try {
      return this.parseExpression(expr);
    } finally {
      this.computing.delete(expr);
    }
  }

  parseExpression(expr) {
    return this.parseAddSubtract(expr);
  }

  parseAddSubtract(expr) {
    let tokens = this.tokenize(expr);
    let result = this.parseMultiplyDivide(tokens[0]);
    let i = 1;

    while (i < tokens.length) {
      const op = tokens[i];
      const right = this.parseMultiplyDivide(tokens[i + 1]);
      if (op === '+') result = result + right;
      else if (op === '-') result = result - right;
      i += 2;
    }
    return result;
  }

  parseMultiplyDivide(expr) {
    if (typeof expr !== 'string') return expr;

    let tokens = this.tokenizeMultDiv(expr);
    let result = this.parsePrimary(tokens[0]);
    let i = 1;

    while (i < tokens.length) {
      const op = tokens[i];
      const right = this.parsePrimary(tokens[i + 1]);
      if (op === '*') result = result * right;
      else if (op === '/') {
        if (right === 0) throw new Error('Division by zero');
        result = result / right;
      }
      i += 2;
    }
    return result;
  }

  parsePrimary(expr) {
    if (typeof expr !== 'string') return expr;

    expr = expr.trim();

    if (expr.startsWith('(') && expr.endsWith(')')) {
      return this.evaluateExpression(expr.substring(1, expr.length - 1));
    }

    if (expr.toUpperCase().startsWith('SUM(')) {
      return this.parseFunction('SUM', expr);
    }
    if (expr.toUpperCase().startsWith('AVG(')) {
      return this.parseFunction('AVG', expr);
    }
    if (expr.toUpperCase().startsWith('MIN(')) {
      return this.parseFunction('MIN', expr);
    }
    if (expr.toUpperCase().startsWith('MAX(')) {
      return this.parseFunction('MAX', expr);
    }
    if (expr.toUpperCase().startsWith('COUNT(')) {
      return this.parseFunction('COUNT', expr);
    }

    if (this.isRange(expr)) {
      return this.getRangeValues(expr);
    }

    if (this.isCellReference(expr)) {
      return this.getCellValue(expr);
    }

    const num = parseFloat(expr);
    if (isNaN(num)) throw new Error('Invalid expression: ' + expr);
    return num;
  }

  parseFunction(func, expr) {
    const match = expr.match(/^([A-Z]+)\((.*)\)$/i);
    if (!match) throw new Error('Invalid function syntax');

    const args = this.parseArguments(match[2]);
    const values = [];

    for (const arg of args) {
      if (this.isRange(arg)) {
        values.push(...this.getRangeValues(arg));
      } else if (this.isCellReference(arg)) {
        values.push(this.getCellValue(arg));
      } else {
        const num = parseFloat(arg);
        if (!isNaN(num)) values.push(num);
      }
    }

    if (values.length === 0) return 0;

    switch (func.toUpperCase()) {
      case 'SUM':
        return values.reduce((a, b) => a + b, 0);
      case 'AVG':
        return values.reduce((a, b) => a + b, 0) / values.length;
      case 'MIN':
        return Math.min(...values);
      case 'MAX':
        return Math.max(...values);
      case 'COUNT':
        return values.length;
      default:
        throw new Error('Unknown function: ' + func);
    }
  }

  parseArguments(str) {
    const args = [];
    let current = '';
    let depth = 0;

    for (let i = 0; i < str.length; i++) {
      const char = str[i];
      if (char === '(') depth++;
      else if (char === ')') depth--;
      else if (char === ',' && depth === 0) {
        args.push(current.trim());
        current = '';
        continue;
      }
      current += char;
    }

    if (current.trim()) args.push(current.trim());
    return args;
  }

  isRange(expr) {
    expr = expr.trim();
    return /^[A-Za-z]+\d+:[A-Za-z]+\d+$/.test(expr);
  }

  isCellReference(expr) {
    expr = expr.trim();
    return /^[A-Za-z]+\d+$/.test(expr);
  }

  getRangeValues(range) {
    const [start, end] = range.split(':');
    const values = [];
    const startCol = this.colLetterToNumber(start.match(/[A-Za-z]+/)[0]);
    const startRow = parseInt(start.match(/\d+/)[0]);
    const endCol = this.colLetterToNumber(end.match(/[A-Za-z]+/)[0]);
    const endRow = parseInt(end.match(/\d+/)[0]);

    for (let r = startRow; r <= endRow; r++) {
      for (let c = startCol; c <= endCol; c++) {
        const addr = this.colNumberToLetter(c) + r;
        const val = this.getCellValue(addr);
        if (val !== 0 || this.cells[addr]) {
          values.push(val);
        }
      }
    }
    return values;
  }

  tokenize(expr) {
    const tokens = [];
    let current = '';

    for (let i = 0; i < expr.length; i++) {
      const char = expr[i];
      if (char === '+' || char === '-') {
        if (current.trim()) tokens.push(current.trim());
        tokens.push(char);
        current = '';
      } else {
        current += char;
      }
    }
    if (current.trim()) tokens.push(current.trim());
    return tokens;
  }

  tokenizeMultDiv(expr) {
    if (typeof expr !== 'string') return [expr];

    const tokens = [];
    let current = '';
    let inParen = 0;
    let inFunc = false;

    for (let i = 0; i < expr.length; i++) {
      const char = expr[i];
      if (char === '(') {
        inParen++;
        current += char;
      } else if (char === ')') {
        inParen--;
        current += char;
      } else if ((char === '*' || char === '/') && inParen === 0) {
        if (current.trim()) tokens.push(current.trim());
        tokens.push(char);
        current = '';
      } else {
        current += char;
      }
    }
    if (current.trim()) tokens.push(current.trim());
    return tokens;
  }

  colLetterToNumber(col) {
    col = col.toUpperCase();
    let num = 0;
    for (let i = 0; i < col.length; i++) {
      num = num * 26 + (col.charCodeAt(i) - 64);
    }
    return num;
  }

  colNumberToLetter(num) {
    let col = '';
    while (num > 0) {
      num--;
      col = String.fromCharCode(65 + num % 26) + col;
      num = Math.floor(num / 26);
    }
    return col;
  }
}

module.exports = FormulaCalculator;

const FormulaCalculator = require('./formula');

class Workbook {
  constructor(db) {
    this.db = db;
  }

  async load(workbookId, revision = null) {
    const snapshot = await this.db.getRevision(workbookId, revision);
    if (!snapshot) throw new Error('Workbook not found');
    return snapshot;
  }

  async getCurrentCells(workbookId) {
    const snapshot = await this.load(workbookId);
    if (!snapshot || !snapshot.sheets || snapshot.sheets.length === 0) {
      return {};
    }
    return snapshot.sheets[0]?.cells || {};
  }

  async calculateCell(workbookId, address) {
    const cells = await this.getCurrentCells(workbookId);
    const calc = new FormulaCalculator(cells);
    const value = cells[address];
    if (!value) return '';
    return calc.calculate(value);
  }

  async updateCell(workbookId, sheetId, cellAddress, newValue, userId) {
    const snapshot = await this.load(workbookId);

    if (!snapshot.sheets || snapshot.sheets.length === 0) {
      throw new Error('No sheets found');
    }

    const sheet = snapshot.sheets[0];
    const previousValue = sheet.cells[cellAddress] || '';

    sheet.cells[cellAddress] = newValue;

    const newRevision = await this.db.saveRevision(workbookId, snapshot);
    await this.db.recordCellChange(workbookId, sheetId, cellAddress, newRevision, previousValue, newValue, userId);

    return { newRevision, previousValue, newValue };
  }

  async updateCells(workbookId, sheetId, updates, userId) {
    const snapshot = await this.load(workbookId);

    if (!snapshot.sheets || snapshot.sheets.length === 0) {
      throw new Error('No sheets found');
    }

    const sheet = snapshot.sheets[0];
    const changes = [];

    for (const [cellAddress, newValue] of Object.entries(updates)) {
      const previousValue = sheet.cells[cellAddress] || '';
      sheet.cells[cellAddress] = newValue;
      changes.push({ cellAddress, previousValue, newValue });
    }

    const newRevision = await this.db.saveRevision(workbookId, snapshot);

    for (const change of changes) {
      await this.db.recordCellChange(
        workbookId, 
        sheetId, 
        change.cellAddress, 
        newRevision, 
        change.previousValue, 
        change.newValue, 
        userId
      );
    }

    return { newRevision, changes };
  }

  async validateWorkbook(snapshot) {
    if (!snapshot.workbook || !snapshot.workbook.id || !snapshot.workbook.title) {
      throw new Error('Missing workbook identity');
    }

    if (!Array.isArray(snapshot.sheets)) {
      throw new Error('Sheets must be an array');
    }

    for (const sheet of snapshot.sheets) {
      if (!sheet.id || !sheet.name) {
        throw new Error('Sheet missing identity or name');
      }
      if (typeof sheet.cells !== 'object') {
        throw new Error('Sheet cells must be an object');
      }
      for (const [addr, value] of Object.entries(sheet.cells)) {
        if (typeof value !== 'string') {
          throw new Error(`Cell ${addr} value must be a string`);
        }
      }
    }

    return true;
  }

  async saveWithConflictResolution(workbookId, basedOnRevision, snapshot, userId) {
    await this.validateWorkbook(snapshot);

    const workbook = await this.db.getWorkbook(workbookId);
    if (!workbook) throw new Error('Workbook not found');

    const currentSnapshot = await this.load(workbookId);
    if (snapshot.workbook.id !== workbookId || snapshot.workbook.title !== currentSnapshot.workbook.title) {
      throw new Error('Workbook identity mismatch');
    }

    if (basedOnRevision !== workbook.current_revision) {
      return await this.mergeChanges(workbookId, basedOnRevision, snapshot, userId);
    }

    const newRevision = await this.db.saveRevision(workbookId, snapshot);

    const currentSheet = currentSnapshot.sheets[0];
    const newSheet = snapshot.sheets[0];

    for (const [addr, newValue] of Object.entries(newSheet.cells)) {
      const previousValue = currentSheet.cells[addr] || '';
      if (previousValue !== newValue) {
        await this.db.recordCellChange(workbookId, newSheet.id, addr, newRevision, previousValue, newValue, userId);
      }
    }

    return { success: true, newRevision };
  }

  async mergeChanges(workbookId, basedOnRevision, incomingSnapshot, userId) {
    const baseSnapshot = await this.load(workbookId, basedOnRevision);
    const currentSnapshot = await this.load(workbookId);

    const baseSheet = baseSnapshot.sheets[0];
    const currentSheet = currentSnapshot.sheets[0];
    const incomingSheet = incomingSnapshot.sheets[0];

    const mergedCells = { ...currentSheet.cells };
    const conflicts = [];

    for (const [addr, incomingValue] of Object.entries(incomingSheet.cells)) {
      const baseValue = baseSheet.cells[addr] || '';
      const currentValue = currentSheet.cells[addr] || '';

      if (baseValue === currentValue) {
        mergedCells[addr] = incomingValue;
      } else if (incomingValue === baseValue) {
        mergedCells[addr] = currentValue;
      } else {
        conflicts.push({
          address: addr,
          current: currentValue,
          incoming: incomingValue,
          base: baseValue
        });
        mergedCells[addr] = currentValue;
      }
    }

    if (conflicts.length > 0) {
      return {
        success: false,
        conflicts,
        message: 'Save rejected due to concurrent changes to the same cells'
      };
    }

    const mergedSnapshot = {
      workbook: currentSnapshot.workbook,
      sheets: currentSnapshot.sheets.map((sheet, index) => ({
        ...sheet,
        cells: index === 0 ? mergedCells : sheet.cells
      }))
    };

    const newRevision = await this.db.saveRevision(workbookId, mergedSnapshot);

    const newSheet = mergedSnapshot.sheets[0];
    for (const [addr, newValue] of Object.entries(newSheet.cells)) {
      const previousValue = currentSheet.cells[addr] || '';
      if (previousValue !== newValue) {
        await this.db.recordCellChange(workbookId, newSheet.id, addr, newRevision, previousValue, newValue, userId);
      }
    }

    return { success: true, newRevision, merged: true };
  }
}

module.exports = Workbook;

const express = require('express');
const path = require('path');
const { v4: uuidv4 } = require('uuid');
const Database = require('./db');
const Workbook = require('./workbook');
const FormulaCalculator = require('./formula');

const app = express();
const db = new Database();
const workbookMgr = new Workbook(db);

const PORT = process.env.PORT || 3000;
const AUTOSAVE_DELAY = 5000;

let autosaveTimers = new Map();
let sessions = new Map();
let presenceData = new Map();

app.use(express.json({ limit: '10mb' }));
app.use(express.static(path.join(__dirname, 'public')));

const users = [
  { id: 'riley', name: 'Riley Stone' },
  { id: 'morgan', name: 'Morgan Lee' },
  { id: 'priya', name: 'Priya Shah' }
];

async function initializeServer() {
  await db.init();
  await db.loadSeedIfNeeded();
  console.log(`✓ Database initialized at ${path.join(__dirname, 'gridforge.sqlite3')}`);
}

app.get('/api/workbooks/:workbookId', async (req, res) => {
  try {
    const { workbookId } = req.params;
    const snapshot = await workbookMgr.load(workbookId);

    const calc = new FormulaCalculator();
    const sheets = snapshot.sheets.map(sheet => ({
      ...sheet,
      cells: Object.fromEntries(
        Object.entries(sheet.cells).map(([addr, value]) => {
          calc.setCells(sheet.cells);
          const result = calc.calculate(value);
          return [addr, { value, result }];
        })
      )
    }));

    res.json({
      workbook: snapshot.workbook,
      sheets,
      revision: (await db.getWorkbook(workbookId)).current_revision,
      users
    });
  } catch (e) {
    console.error('Error loading workbook:', e);
    res.status(404).json({ error: e.message });
  }
});

app.get('/api/workbooks/:workbookId/revisions', async (req, res) => {
  try {
    const { workbookId } = req.params;
    const revisions = await db.getRevisions(workbookId);
    res.json({ revisions });
  } catch (e) {
    res.status(500).json({ error: e.message });
  }
});

app.get('/api/workbooks/:workbookId/revisions/:revision', async (req, res) => {
  try {
    const { workbookId, revision } = req.params;
    const revNum = parseInt(revision);
    const snapshot = await workbookMgr.load(workbookId, revNum);

    const calc = new FormulaCalculator();
    const sheets = snapshot.sheets.map(sheet => ({
      ...sheet,
      cells: Object.fromEntries(
        Object.entries(sheet.cells).map(([addr, value]) => {
          calc.setCells(sheet.cells);
          const result = calc.calculate(value);
          return [addr, { value, result }];
        })
      )
    }));

    res.json({
      workbook: snapshot.workbook,
      sheets,
      revision: revNum
    });
  } catch (e) {
    res.status(404).json({ error: e.message });
  }
});

app.get('/api/workbooks/:workbookId/sheets/:sheetId/cells/:address/history', async (req, res) => {
  try {
    const { workbookId, sheetId, address } = req.params;
    const history = await db.getCellHistory(workbookId, sheetId, address);
    res.json({ history });
  } catch (e) {
    res.status(500).json({ error: e.message });
  }
});

app.post('/api/sessions', (req, res) => {
  try {
    const { workbookId, userId } = req.body;

    if (!workbookId || !userId) {
      return res.status(400).json({ error: 'Missing workbookId or userId' });
    }

    const validUser = users.find(u => u.id === userId);
    if (!validUser) {
      return res.status(400).json({ error: 'Invalid user' });
    }

    const sessionId = uuidv4();
    const session = {
      sessionId,
      workbookId,
      userId,
      createdAt: new Date()
    };

    sessions.set(sessionId, session);

    if (!presenceData.has(workbookId)) {
      presenceData.set(workbookId, []);
    }

    presenceData.get(workbookId).push({
      sessionId,
      userId,
      cell: null,
      color: getColorForSession(sessionId, userId)
    });

    res.json({ sessionId, session });
  } catch (e) {
    res.status(500).json({ error: e.message });
  }
});

app.delete('/api/sessions/:sessionId', (req, res) => {
  try {
    const { sessionId } = req.params;
    const session = sessions.get(sessionId);

    if (!session) {
      return res.status(404).json({ error: 'Session not found' });
    }

    sessions.delete(sessionId);

    for (const [wbId, presence] of presenceData) {
      const idx = presence.findIndex(p => p.sessionId === sessionId);
      if (idx !== -1) {
        presence.splice(idx, 1);
      }
    }

    res.json({ success: true });
  } catch (e) {
    res.status(500).json({ error: e.message });
  }
});

app.put('/api/workbooks/:workbookId', async (req, res) => {
  try {
    const { workbookId } = req.params;
    const { snapshot, basedOnRevision, sessionId, changes } = req.body;

    if (!sessionId || !sessions.has(sessionId)) {
      return res.status(401).json({ error: 'Invalid session' });
    }

    const session = sessions.get(sessionId);
    if (session.workbookId !== workbookId) {
      return res.status(401).json({ error: 'Session workbook mismatch' });
    }

    if (!snapshot || typeof basedOnRevision !== 'number') {
      return res.status(400).json({ error: 'Missing snapshot or basedOnRevision' });
    }

    const result = await workbookMgr.saveWithConflictResolution(
      workbookId,
      basedOnRevision,
      snapshot,
      session.userId
    );

    res.json(result);
  } catch (e) {
    console.error('Error saving workbook:', e);
    res.status(400).json({ error: e.message });
  }
});

app.get('/api/presence/:workbookId', (req, res) => {
  try {
    const { workbookId } = req.params;
    const presence = presenceData.get(workbookId) || [];

    const enrichedPresence = presence.map(p => ({
      ...p,
      user: users.find(u => u.id === p.userId)
    }));

    res.json({ presence: enrichedPresence });
  } catch (e) {
    res.status(500).json({ error: e.message });
  }
});

app.put('/api/presence/:sessionId', (req, res) => {
  try {
    const { sessionId } = req.params;
    const { cell, range } = req.body;

    const session = sessions.get(sessionId);
    if (!session) {
      return res.status(404).json({ error: 'Session not found' });
    }

    const workbookId = session.workbookId;
    const presence = presenceData.get(workbookId) || [];
    const p = presence.find(pr => pr.sessionId === sessionId);

    if (p) {
      p.cell = cell;
      p.range = range;
    }

    res.json({ success: true });
  } catch (e) {
    res.status(500).json({ error: e.message });
  }
});

app.post('/api/calculate', (req, res) => {
  try {
    const { cells, address } = req.body;

    if (!cells || !address) {
      return res.status(400).json({ error: 'Missing cells or address' });
    }

    const calc = new FormulaCalculator(cells);
    const value = cells[address];
    const result = calc.calculate(value);

    res.json({ address, value, result });
  } catch (e) {
    res.status(400).json({ error: e.message });
  }
});

app.use((err, req, res, next) => {
  console.error('Server error:', err);
  res.status(500).json({ error: 'Internal server error' });
});

function getColorForSession(sessionId, userId) {
  const colors = ['#FF6B6B', '#4ECDC4', '#45B7D1', '#FFA07A', '#98D8C8', '#F7DC6F'];
  const hash = (sessionId + userId).split('').reduce((acc, char) => {
    return acc + char.charCodeAt(0);
  }, 0);
  return colors[hash % colors.length];
}

async function startServer() {
  try {
    await initializeServer();

    app.listen(PORT, '0.0.0.0', () => {
      console.log(`GridForge server running on port ${PORT}`);
      console.log(`Open http://localhost:${PORT} in your browser`);
    });
  } catch (error) {
    console.error('Failed to start server:', error);
    process.exit(1);
  }
}

process.on('SIGINT', async () => {
  console.log('Shutting down...');
  await db.close();
  process.exit(0);
});

startServer();

