class FormulaHelper {
  static isFormula(value) {
    return typeof value === 'string' && value.startsWith('=');
  }

  static getFormulaFunctions() {
    return ['SUM', 'AVG', 'MIN', 'MAX', 'COUNT'];
  }

  static suggestFunctions(input) {
    const functions = this.getFormulaFunctions();
    const suggestions = [];

    for (const func of functions) {
      if (func.startsWith(input.toUpperCase())) {
        suggestions.push(func + '()');
      }
    }
    return suggestions;
  }

  static extractCellReferences(formula) {
    const references = [];
    const regex = /([A-Z]+\d+(?::[A-Z]+\d+)?)/g;
    let match;
    while ((match = regex.exec(formula)) !== null) {
      references.push(match[1]);
    }
    return [...new Set(references)];
  }

  static colLetterToNumber(col) {
    col = col.toUpperCase();
    let num = 0;
    for (let i = 0; i < col.length; i++) {
      num = num * 26 + (col.charCodeAt(i) - 64);
    }
    return num;
  }

  static colNumberToLetter(num) {
    let col = '';
    while (num > 0) {
      num--;
      col = String.fromCharCode(65 + num % 26) + col;
      num = Math.floor(num / 26);
    }
    return col;
  }

  static parseRange(range) {
    const [start, end] = range.split(':');
    if (!end) return [start];

    const startCol = this.colLetterToNumber(start.match(/[A-Z]+/)[0]);
    const startRow = parseInt(start.match(/\d+/)[0]);
    const endCol = this.colLetterToNumber(end.match(/[A-Z]+/)[0]);
    const endRow = parseInt(end.match(/\d+/)[0]);

    const cells = [];
    for (let r = startRow; r <= endRow; r++) {
      for (let c = startCol; c <= endCol; c++) {
        cells.push(this.colNumberToLetter(c) + r);
      }
    }
    return cells;
  }

  static adjustFormula(formula, fromCell, toCell) {
    const fromCol = this.colLetterToNumber(fromCell.match(/[A-Z]+/)[0]);
    const fromRow = parseInt(fromCell.match(/\d+/)[0]);
    const toCol = this.colLetterToNumber(toCell.match(/[A-Z]+/)[0]);
    const toRow = parseInt(toCell.match(/\d+/)[0]);

    const colOffset = toCol - fromCol;
    const rowOffset = toRow - fromRow;

    return formula.replace(/([A-Z]+)(\d+)(?=[^\d]|$)/g, (match, col, row) => {
      const c = this.colLetterToNumber(col);
      const r = parseInt(row);
      return this.colNumberToLetter(c + colOffset) + (r + rowOffset);
    });
  }

  static isCellReference(str) {
    return /^[A-Z]+\d+$/.test(str.trim());
  }

  static isRangeReference(str) {
    return /^[A-Z]+\d+:[A-Z]+\d+$/.test(str.trim());
  }
}

class Grid {
  constructor(containerId, rows = 80, cols = 20) {
    this.container = document.getElementById(containerId);
    this.rows = rows;
    this.cols = cols;
    this.cells = {};
    this.selectedStart = null;
    this.selectedEnd = null;
    this.editingCell = null;
    this.clipboard = null;
    this.clipboardMode = null;
    this.presenceIndicators = new Map();
    this.undoStack = [];
    this.redoStack = [];
    this.cellElements = new Map();

    this.render();
    this.attachEventListeners();
  }

  render() {
    this.container.innerHTML = '';

    const wrapper = document.createElement('div');
    wrapper.className = 'grid-wrapper';

    const header = document.createElement('div');
    header.className = 'grid-header';

    const corner = document.createElement('div');
    corner.className = 'grid-header-corner';
    header.appendChild(corner);

    for (let col = 1; col <= this.cols; col++) {
      const cell = document.createElement('div');
      cell.className = 'grid-header-cell';
      cell.textContent = FormulaHelper.colNumberToLetter(col);
      header.appendChild(cell);
    }
    wrapper.appendChild(header);

    for (let row = 1; row <= this.rows; row++) {
      const rowDiv = document.createElement('div');
      rowDiv.className = 'grid-row';

      const rowNum = document.createElement('div');
      rowNum.className = 'grid-row-number';
      rowNum.textContent = row;
      rowDiv.appendChild(rowNum);

      for (let col = 1; col <= this.cols; col++) {
        const address = FormulaHelper.colNumberToLetter(col) + row;
        const cell = document.createElement('div');
        cell.className = 'grid-cell';
        cell.dataset.address = address;

        const content = document.createElement('div');
        content.className = 'grid-cell-content';
        content.textContent = '';
        cell.appendChild(content);

        cell.addEventListener('click', (e) => this.selectCell(address, e));
        cell.addEventListener('dblclick', () => this.editCell(address));
        cell.addEventListener('mousedown', (e) => this.handleMouseDown(e, address));
        cell.addEventListener('mouseover', (e) => this.handleMouseOver(e, address));
        cell.addEventListener('mouseup', (e) => this.handleMouseUp(e, address));
        cell.addEventListener('contextmenu', (e) => this.handleContextMenu(e, address));

        rowDiv.appendChild(cell);
        this.cellElements.set(address, cell);
      }
      wrapper.appendChild(rowDiv);
    }

    this.container.appendChild(wrapper);
  }

  setCellContent(address, value, result) {
    const cell = this.cellElements.get(address);
    if (!cell) return;

    this.cells[address] = value;
    const content = cell.querySelector('.grid-cell-content');

    cell.classList.remove('formula', 'number', 'error', 'in-range', 'in-selection');

    if (FormulaHelper.isFormula(value)) {
      cell.classList.add('formula');
    }

    if (typeof result === 'string' && result.startsWith('#ERROR')) {
      cell.classList.add('error');
      content.textContent = result;
    } else if (typeof result === 'number') {
      cell.classList.add('number');
      content.textContent = result.toString();
    } else {
      content.textContent = result.toString();
    }
  }

  selectCell(address, event) {
    if (event && event.shiftKey && this.selectedStart) {
      this.selectedEnd = address;
      this.updateSelectionDisplay();
    } else if (event && event.ctrlKey) {
      // Multi-select handled separately
    } else {
      this.selectedStart = address;
      this.selectedEnd = null;
      this.updateSelectionDisplay();
    }

    if (this.onSelectionChanged) {
      this.onSelectionChanged(this.selectedStart, this.selectedEnd);
    }
  }

  updateSelectionDisplay() {
    this.cellElements.forEach((cell) => {
      cell.classList.remove('selected', 'in-selection');
    });

    if (this.selectedStart) {
      const startCell = this.cellElements.get(this.selectedStart);
      if (startCell) startCell.classList.add('selected');
    }

    if (this.selectedStart && this.selectedEnd) {
      const cells = this.getSelectionCells();
      for (const addr of cells) {
        const cell = this.cellElements.get(addr);
        if (cell) cell.classList.add('in-selection');
      }
    }
  }

  getSelectionCells() {
    if (!this.selectedStart) return [];
    if (!this.selectedEnd) return [this.selectedStart];

    const startCol = FormulaHelper.colLetterToNumber(this.selectedStart.match(/[A-Z]+/)[0]);
    const startRow = parseInt(this.selectedStart.match(/\d+/)[0]);
    const endCol = FormulaHelper.colLetterToNumber(this.selectedEnd.match(/[A-Z]+/)[0]);
    const endRow = parseInt(this.selectedEnd.match(/\d+/)[0]);

    const minCol = Math.min(startCol, endCol);
    const maxCol = Math.max(startCol, endCol);
    const minRow = Math.min(startRow, endRow);
    const maxRow = Math.max(startRow, endRow);

    const cells = [];
    for (let r = minRow; r <= maxRow; r++) {
      for (let c = minCol; c <= maxCol; c++) {
        cells.push(FormulaHelper.colNumberToLetter(c) + r);
      }
    }
    return cells;
  }

  editCell(address) {
    this.editingCell = address;
    const cell = this.cellElements.get(address);
    if (!cell) return;

    const value = this.cells[address] || '';
    cell.innerHTML = `<input type="text" class="grid-cell-edit" value="${this.escapeHtml(value)}">`;
    const input = cell.querySelector('input');
    input.focus();
    input.select();

    input.addEventListener('blur', () => this.finishEditing(address));
    input.addEventListener('keydown', (e) => this.handleEditKeydown(e, address));
  }

  finishEditing(address) {
    const cell = this.cellElements.get(address);
    if (!cell) return;

    const input = cell.querySelector('input');
    if (!input) return;

    const newValue = input.value;
    const oldValue = this.cells[address] || '';

    if (newValue !== oldValue) {
      this.cells[address] = newValue;
      if (this.onCellChanged) {
        this.onCellChanged(address, oldValue, newValue);
      }
    }

    this.editingCell = null;
    this.updateSelectionDisplay();
  }

  handleEditKeydown(event, address) {
    if (event.key === 'Enter') {
      this.finishEditing(address);
      this.navigateCell(address, 0, 1);
    } else if (event.key === 'Escape') {
      this.editingCell = null;
      this.updateSelectionDisplay();
    } else if (event.key === 'Tab') {
      event.preventDefault();
      this.finishEditing(address);
      this.navigateCell(address, event.shiftKey ? -1 : 1, 0);
    }
  }

  navigateCell(from, colDelta, rowDelta) {
    const col = FormulaHelper.colLetterToNumber(from.match(/[A-Z]+/)[0]);
    const row = parseInt(from.match(/\d+/)[0]);

    const newCol = col + colDelta;
    const newRow = row + rowDelta;

    if (newCol >= 1 && newCol <= this.cols && newRow >= 1 && newRow <= this.rows) {
      const newAddr = FormulaHelper.colNumberToLetter(newCol) + newRow;
      this.selectCell(newAddr);
      this.scrollToCell(newAddr);
    }
  }

  scrollToCell(address) {
    const cell = this.cellElements.get(address);
    if (cell) {
      cell.scrollIntoView({ behavior: 'auto', block: 'nearest', inline: 'nearest' });
    }
  }

  copy() {
    const cells = this.getSelectionCells();
    const data = {};
    for (const addr of cells) {
      data[addr] = this.cells[addr] || '';
    }
    this.clipboard = { data, range: cells, startCell: this.selectedStart };
    this.clipboardMode = 'copy';
  }

  cut() {
    this.copy();
    this.clipboardMode = 'cut';
  }

  paste() {
    if (!this.clipboard) return;

    const startCell = this.selectedStart;
    const startCol = FormulaHelper.colLetterToNumber(startCell.match(/[A-Z]+/)[0]);
    const startRow = parseInt(startCell.match(/\d+/)[0]);

    const clipStartCol = FormulaHelper.colLetterToNumber(this.clipboard.startCell.match(/[A-Z]+/)[0]);
    const clipStartRow = parseInt(this.clipboard.startCell.match(/\d+/)[0]);

    const updates = {};
    const action = {
      type: 'paste',
      updates: {},
      startCell,
      originalClipboardMode: this.clipboardMode
    };

    for (const addr in this.clipboard.data) {
      const col = FormulaHelper.colLetterToNumber(addr.match(/[A-Z]+/)[0]);
      const row = parseInt(addr.match(/\d+/)[0]);

      const newCol = startCol + (col - clipStartCol);
      const newRow = startRow + (row - clipStartRow);

      if (newCol >= 1 && newCol <= this.cols && newRow >= 1 && newRow <= this.rows) {
        const newAddr = FormulaHelper.colNumberToLetter(newCol) + newRow;
        let newValue = this.clipboard.data[addr];

        if (FormulaHelper.isFormula(newValue)) {
          const colDelta = newCol - col;
          const rowDelta = newRow - row;
          newValue = newValue.substring(1);
          newValue = newValue.replace(/([A-Z]+)(\d+)/g, (match, c, r) => {
            const nc = FormulaHelper.colLetterToNumber(c) + colDelta;
            const nr = parseInt(r) + rowDelta;
            if (nc >= 1 && nr >= 1 && nc <= this.cols && nr <= this.rows) {
              return FormulaHelper.colNumberToLetter(nc) + nr;
            }
            return match;
          });
          newValue = '=' + newValue;
        }

        const oldValue = this.cells[newAddr] || '';
        updates[newAddr] = newValue;
        action.updates[newAddr] = { old: oldValue, new: newValue };
        this.cells[newAddr] = newValue;
      }
    }

    if (this.clipboardMode === 'cut') {
      this.clipboard = null;
      this.clipboardMode = null;
    }

    this.undoStack.push(action);
    this.redoStack = [];

    if (this.onPaste) {
      this.onPaste(updates);
    }
  }

  pasteText(text) {
    const rows = text.trim().split(/[\r\n]+/);
    const updates = {};
    const action = {
      type: 'paste',
      updates: {},
      startCell: this.selectedStart
    };

    const startCell = this.selectedStart;
    const startCol = FormulaHelper.colLetterToNumber(startCell.match(/[A-Z]+/)[0]);
    const startRow = parseInt(startCell.match(/\d+/)[0]);

    for (let r = 0; r < rows.length; r++) {
      const cols = rows[r].split(/\t/);
      for (let c = 0; c < cols.length; c++) {
        const newCol = startCol + c;
        const newRow = startRow + r;
        if (newCol <= this.cols && newRow <= this.rows) {
          const addr = FormulaHelper.colNumberToLetter(newCol) + newRow;
          const newValue = cols[c];
          const oldValue = this.cells[addr] || '';
          updates[addr] = newValue;
          action.updates[addr] = { old: oldValue, new: newValue };
          this.cells[addr] = newValue;
        }
      }
    }

    this.undoStack.push(action);
    this.redoStack = [];

    if (this.onPaste) {
      this.onPaste(updates);
    }
  }

  fill(direction) {
    const cells = this.getSelectionCells();
    if (cells.length < 2) return;

    const updates = {};
    const action = {
      type: 'fill',
      direction,
      updates: {},
      startCell: this.selectedStart
    };

    let sourceCells = [];
    let targetCells = [];

    if (direction === 'down') {
      const rows = new Set(cells.map(c => parseInt(c.match(/\d+/)[0])));
      const minRow = Math.min(...rows);
      const maxRow = Math.max(...rows);
      sourceCells = cells.filter(c => parseInt(c.match(/\d+/)[0]) === minRow);
      targetCells = cells.filter(c => parseInt(c.match(/\d+/)[0]) > minRow);
    } else if (direction === 'right') {
      const cols = new Set(cells.map(c => c.match(/[A-Z]+/)[0]));
      const sortedCols = Array.from(cols).sort();
      const minCol = sortedCols[0];
      const maxCol = sortedCols[sortedCols.length - 1];
      sourceCells = cells.filter(c => c.match(/[A-Z]+/)[0] === minCol);
      targetCells = cells.filter(c => c.match(/[A-Z]+/)[0] !== minCol);
    }

    if (sourceCells.length === 0) return;

    for (const targetCell of targetCells) {
      const sourceCell = sourceCells[0];
      let value = this.cells[sourceCell] || '';

      if (FormulaHelper.isFormula(value)) {
        value = FormulaHelper.adjustFormula(value, sourceCell, targetCell);
      } else {
        const sourceVal = parseFloat(this.cells[sourceCell] || '');
        if (!isNaN(sourceVal)) {
          const sourceRow = parseInt(sourceCell.match(/\d+/)[0]);
          const targetRow = parseInt(targetCell.match(/\d+/)[0]);
          const rowDelta = targetRow - sourceRow;
          value = (sourceVal + rowDelta).toString();
        }
      }

      const oldValue = this.cells[targetCell] || '';
      updates[targetCell] = value;
      action.updates[targetCell] = { old: oldValue, new: value };
      this.cells[targetCell] = value;
    }

    this.undoStack.push(action);
    this.redoStack = [];

    if (this.onFill) {
      this.onFill(updates);
    }
  }

  undo() {
    if (this.undoStack.length === 0) return false;

    const action = this.undoStack.pop();
    this.redoStack.push(action);

    const updates = {};
    for (const addr in action.updates) {
      const old = action.updates[addr].old;
      this.cells[addr] = old;
      updates[addr] = old;
    }

    if (this.onUndo) {
      this.onUndo(updates);
    }
    return true;
  }

  redo() {
    if (this.redoStack.length === 0) return false;

    const action = this.redoStack.pop();
    this.undoStack.push(action);

    const updates = {};
    for (const addr in action.updates) {
      const newVal = action.updates[addr].new;
      this.cells[addr] = newVal;
      updates[addr] = newVal;
    }

    if (this.onRedo) {
      this.onRedo(updates);
    }
    return true;
  }

  addPresenceIndicator(sessionId, userId, color, cell, range) {
    const address = cell;
    const cellEl = this.cellElements.get(address);
    if (!cellEl) return;

    let indicator = this.presenceIndicators.get(sessionId);
    if (!indicator) {
      indicator = document.createElement('div');
      indicator.className = 'presence-indicator';
      indicator.style.borderColor = color;
      indicator.dataset.sessionId = sessionId;
      cellEl.appendChild(indicator);
      this.presenceIndicators.set(sessionId, indicator);
    }
  }

  removePresenceIndicator(sessionId) {
    const indicator = this.presenceIndicators.get(sessionId);
    if (indicator) {
      indicator.remove();
      this.presenceIndicators.delete(sessionId);
    }
  }

  handleMouseDown(event, address) {
    if (event.button !== 0) return;
    this.selectCell(address, event);
  }

  handleMouseOver(event, address) {
    if (event.buttons !== 1) return;
    this.selectedEnd = address;
    this.updateSelectionDisplay();
  }

  handleMouseUp(event, address) {
    // Selection already handled
  }

  handleContextMenu(event, address) {
    event.preventDefault();
  }

  attachEventListeners() {
    document.addEventListener('keydown', (e) => {
      if (this.editingCell) return;

      const ctrl = e.ctrlKey || e.metaKey;

      if (ctrl && e.key.toLowerCase() === 'c') {
        e.preventDefault();
        this.copy();
      } else if (ctrl && e.key.toLowerCase() === 'x') {
        e.preventDefault();
        this.cut();
      } else if (ctrl && e.key.toLowerCase() === 'v') {
        e.preventDefault();
        this.paste();
      } else if (ctrl && e.key.toLowerCase() === 'z' && !e.shiftKey) {
        e.preventDefault();
        this.undo();
        if (this.onUpdated) this.onUpdated();
      } else if ((ctrl && e.key.toLowerCase() === 'y') || (ctrl && e.shiftKey && e.key.toLowerCase() === 'z')) {
        e.preventDefault();
        this.redo();
        if (this.onUpdated) this.onUpdated();
      } else if (e.key.toLowerCase() === 'arrowup') {
        e.preventDefault();
        this.navigateCell(this.selectedStart, 0, -1);
      } else if (e.key.toLowerCase() === 'arrowdown') {
        e.preventDefault();
        this.navigateCell(this.selectedStart, 0, 1);
      } else if (e.key.toLowerCase() === 'arrowleft') {
        e.preventDefault();
        this.navigateCell(this.selectedStart, -1, 0);
      } else if (e.key.toLowerCase() === 'arrowright') {
        e.preventDefault();
        this.navigateCell(this.selectedStart, 1, 0);
      } else if (e.key === 'Delete' || e.key === 'Backspace') {
        e.preventDefault();
        this.deleteSelection();
      } else if (ctrl && e.key.toLowerCase() === 'd') {
        e.preventDefault();
        this.fill('down');
      } else if (ctrl && e.key.toLowerCase() === 'r') {
        e.preventDefault();
        this.fill('right');
      }
    });
  }

  deleteSelection() {
    const cells = this.getSelectionCells();
    const updates = {};
    const action = {
      type: 'delete',
      updates: {}
    };

    for (const addr of cells) {
      const oldValue = this.cells[addr] || '';
      updates[addr] = '';
      action.updates[addr] = { old: oldValue, new: '' };
      this.cells[addr] = '';
    }

    this.undoStack.push(action);
    this.redoStack = [];

    if (this.onDelete) {
      this.onDelete(updates);
    }
  }

  find(text, options = {}) {
    const results = [];
    for (const [addr, value] of Object.entries(this.cells)) {
      let match = false;
      const searchValue = options.matchCase ? value : value.toLowerCase();
      const searchText = options.matchCase ? text : text.toLowerCase();

      if (options.wholeCell) {
        match = searchValue === searchText;
      } else {
        match = searchValue.includes(searchText);
      }

      if (match) {
        results.push(addr);
      }
    }
    return results;
  }

  replace(text, replacement, options = {}) {
    const results = this.find(text, options);
    const updates = {};
    const action = {
      type: 'replace',
      updates: {}
    };

    for (const addr of results) {
      const value = this.cells[addr] || '';
      const searchValue = options.matchCase ? value : value.toLowerCase();
      const searchText = options.matchCase ? text : text.toLowerCase();

      let newValue;
      if (options.wholeCell) {
        newValue = searchValue === searchText ? replacement : value;
      } else {
        newValue = value.replace(
          new RegExp(text.replace(/[.*+?^${}()|[\]\\]/g, '\\$&'), options.matchCase ? 'g' : 'gi'),
          replacement
        );
      }

      if (newValue !== value) {
        updates[addr] = newValue;
        action.updates[addr] = { old: value, new: newValue };
        this.cells[addr] = newValue;
      }
    }

    if (Object.keys(updates).length > 0) {
      this.undoStack.push(action);
      this.redoStack = [];
    }

    return updates;
  }

  escapeHtml(text) {
    const div = document.createElement('div');
    div.textContent = text;
    return div.innerHTML;
  }

  getNameBoxValue() {
    const start = this.selectedStart;
    const end = this.selectedEnd;

    if (!start) return '';
    if (!end || start === end) return start;

    return start + ':' + end;
  }

  setNameBoxValue(value) {
    const parts = value.split(':');
    if (parts.length === 1 && FormulaHelper.isCellReference(value)) {
      this.selectCell(value);
      this.scrollToCell(value);
    } else if (parts.length === 2 && FormulaHelper.isCellReference(parts[0]) && FormulaHelper.isCellReference(parts[1])) {
      this.selectedStart = parts[0];
      this.selectedEnd = parts[1];
      this.updateSelectionDisplay();
      this.scrollToCell(parts[0]);
    }
  }

  getFormulaBarValue() {
    return this.cells[this.selectedStart] || '';
  }

  setFormulaBarValue(value) {
    if (!this.selectedStart) return;
    const oldValue = this.cells[this.selectedStart] || '';
    this.cells[this.selectedStart] = value;

    if (value !== oldValue && this.onCellChanged) {
      this.onCellChanged(this.selectedStart, oldValue, value);
    }
  }
}

class GridForgeApp {
  constructor() {
    this.workbookId = 'ops-plan';
    this.userId = null;
    this.sessionId = null;
    this.users = [];
    this.grid = null;
    this.currentRevision = 0;
    this.autosaveTimer = null;
    this.presenceTimer = null;
    this.lastSavedSnapshot = null;
    this.findCurrentIndex = 0;
    this.findResults = [];
  }

  async init() {
    try {
      const data = await api.getWorkbook(this.workbookId);
      this.users = data.users;
      this.currentRevision = data.revision;
      this.showUserSelection();
    } catch (error) {
      console.error('Failed to load workbook:', error);
      alert('Failed to load workbook: ' + error.message);
    }
  }

  showUserSelection() {
    const modal = document.getElementById('user-select-modal');
    const buttons = document.getElementById('user-buttons');

    buttons.innerHTML = '';
    for (const user of this.users) {
      const btn = document.createElement('button');
      btn.className = 'user-btn';
      btn.textContent = user.name + ' (' + user.id + ')';
      btn.addEventListener('click', () => this.selectUser(user.id));
      buttons.appendChild(btn);
    }

    modal.style.display = 'flex';
  }

  async selectUser(userId) {
    this.userId = userId;

    try {
      const response = await api.createSession(this.workbookId, userId);
      this.sessionId = response.sessionId;

      document.getElementById('user-select-modal').style.display = 'none';
      document.getElementById('main-app').style.display = 'flex';

      await this.loadWorkbook();
      this.attachEventListeners();
      this.startAutosave();
      this.startPresenceUpdates();
    } catch (error) {
      console.error('Failed to create session:', error);
      alert('Failed to create session: ' + error.message);
    }
  }

  async loadWorkbook() {
    try {
      const data = await api.getWorkbook(this.workbookId);

      document.getElementById('workbook-title').textContent = data.workbook.title;
      document.getElementById('user-indicator').textContent = this.users.find(u => u.id === this.userId)?.name || this.userId;

      this.currentRevision = data.revision;
      this.lastSavedSnapshot = this.buildSnapshot(data);

      this.grid = new Grid('grid', 80, 20);

      for (const sheet of data.sheets) {
        for (const [addr, cellData] of Object.entries(sheet.cells)) {
          const value = cellData.value;
          const result = cellData.result;
          this.grid.setCellContent(addr, value, result);
        }
      }

      this.grid.selectedStart = 'A1';
      this.grid.updateSelectionDisplay();
      this.updateFormulaBar();
      this.updateNameBox();
      this.updateSaveStatus('saved');

      this.grid.onCellChanged = (addr, oldValue, newValue) => this.handleCellChange(addr, oldValue, newValue);
      this.grid.onPaste = (updates) => this.handlePaste(updates);
      this.grid.onFill = (updates) => this.handleFill(updates);
      this.grid.onDelete = (updates) => this.handleDelete(updates);
      this.grid.onSelectionChanged = () => this.onSelectionChanged();
      this.grid.onUndo = (updates) => this.handleUndo(updates);
      this.grid.onRedo = (updates) => this.handleRedo(updates);
      this.grid.onUpdated = () => this.updateFormulaBar();
    } catch (error) {
      console.error('Failed to load workbook:', error);
      alert('Failed to load workbook: ' + error.message);
    }
  }

  buildSnapshot(data) {
    const sheets = data.sheets.map(sheet => ({
      id: sheet.id,
      name: sheet.name,
      cells: Object.fromEntries(
        Object.entries(sheet.cells).map(([addr, cellData]) => [addr, cellData.value])
      )
    }));

    return {
      workbook: data.workbook,
      sheets
    };
  }

  handleCellChange(addr, oldValue, newValue) {
    this.updateSaveStatus('unsaved');
    this.updateFormulaBar();
    this.updateNameBox();
    this.scheduleSave();
  }

  handlePaste(updates) {
    this.updateSaveStatus('unsaved');
    this.refreshCellCalculations();
    this.scheduleSave();
  }

  handleFill(updates) {
    this.updateSaveStatus('unsaved');
    this.refreshCellCalculations();
    this.scheduleSave();
  }

  handleDelete(updates) {
    this.updateSaveStatus('unsaved');
    this.refreshCellCalculations();
    this.scheduleSave();
  }

  handleUndo(updates) {
    this.updateSaveStatus('unsaved');
    this.refreshCellCalculations();
    this.updateFormulaBar();
    this.updateNameBox();
  }

  handleRedo(updates) {
    this.updateSaveStatus('unsaved');
    this.refreshCellCalculations();
    this.updateFormulaBar();
    this.updateNameBox();
  }

  onSelectionChanged() {
    this.updateFormulaBar();
    this.updateNameBox();
    if (this.sessionId) {
      this.updatePresence();
    }
  }

  updateFormulaBar() {
    if (!this.grid.selectedStart) {
      document.getElementById('formula-input').value = '';
      return;
    }

    const value = this.grid.cells[this.grid.selectedStart] || '';
    document.getElementById('formula-input').value = value;
  }

  updateNameBox() {
    if (!this.grid.selectedStart) {
      document.getElementById('name-box').value = '';
      return;
    }

    const nameBoxValue = this.grid.getNameBoxValue();
    document.getElementById('name-box').value = nameBoxValue;
  }

  updateSaveStatus(status) {
    const statusEl = document.getElementById('save-status');
    statusEl.className = 'save-status ' + status;

    if (status === 'saving') {
      statusEl.textContent = 'Saving...';
    } else if (status === 'saved') {
      statusEl.textContent = 'Saved';
    } else if (status === 'unsaved') {
      statusEl.textContent = 'Unsaved changes';
    } else if (status === 'error') {
      statusEl.textContent = 'Save failed';
    }
  }

  refreshCellCalculations() {
    for (const addr of Object.keys(this.grid.cells)) {
      const value = this.grid.cells[addr];
      if (FormulaHelper.isFormula(value)) {
        api.calculate(this.grid.cells, addr).then(data => {
          this.grid.setCellContent(addr, value, data.result);
        }).catch(err => {
          this.grid.setCellContent(addr, value, '#ERROR: ' + err.message);
        });
      }
    }
  }

  scheduleSave() {
    clearTimeout(this.autosaveTimer);
    this.autosaveTimer = setTimeout(() => this.save(), 5000);
  }

  async save() {
    try {
      this.updateSaveStatus('saving');

      const snapshot = this.buildSnapshot({
        workbook: { id: this.workbookId, title: document.getElementById('workbook-title').textContent },
        sheets: [{
          id: 'plan',
          name: 'Plan',
          cells: {}
        }]
      });

      snapshot.sheets[0].cells = this.grid.cells;

      const result = await api.saveWorkbook(
        this.workbookId,
        snapshot,
        this.currentRevision,
        this.sessionId
      );

      if (result.success) {
        this.currentRevision = result.newRevision;
        this.lastSavedSnapshot = snapshot;
        this.updateSaveStatus('saved');
      } else if (result.conflicts) {
        this.handleSaveConflict(result.conflicts);
      }
    } catch (error) {
      console.error('Save failed:', error);
      this.updateSaveStatus('error');
    }
  }

  handleSaveConflict(conflicts) {
    const msg = 'Save conflict: Changes were made to the same cells by another user.\n\n' +
      conflicts.map(c => `${c.address}: Was "${c.current}", you tried "${c.incoming}"`).join('\n') +
      '\n\nYour changes have not been saved.';
    alert(msg);
    this.updateSaveStatus('error');
  }

  startAutosave() {
    this.autosaveTimer = setTimeout(() => this.save(), 5000);
  }

  startPresenceUpdates() {
    this.presenceTimer = setInterval(() => this.updatePresenceDisplay(), 3000);
  }

  updatePresence() {
    if (!this.sessionId) return;

    const selection = this.grid.getSelectionCells();
    const cell = this.grid.selectedStart;
    const range = selection.length > 1 ? this.grid.selectedStart + ':' + this.grid.selectedEnd : null;

    api.updatePresence(this.sessionId, cell, range).catch(err => {
      console.error('Failed to update presence:', err);
    });
  }

  async updatePresenceDisplay() {
    try {
      const data = await api.getPresence(this.workbookId);
      const panel = document.getElementById('presence-panel');
      const list = document.getElementById('presence-list');

      list.innerHTML = '';

      for (const p of data.presence) {
        if (p.sessionId === this.sessionId) continue;

        const item = document.createElement('div');
        item.className = 'presence-item';
        item.style.borderLeftColor = p.color;

        const name = document.createElement('div');
        name.className = 'presence-item-name';
        name.textContent = p.user?.name || p.userId;
        item.appendChild(name);

        if (p.cell) {
          const cellInfo = document.createElement('div');
          cellInfo.className = 'presence-item-cell';
          cellInfo.textContent = p.cell;
          item.appendChild(cellInfo);
        }

        list.appendChild(item);

        if (p.cell) {
          this.grid.addPresenceIndicator(p.sessionId, p.userId, p.color, p.cell, p.range);
        }
      }

      if (data.presence.length > 0) {
        panel.classList.add('active');
      }
    } catch (error) {
      console.error('Failed to update presence:', error);
    }
  }

  attachEventListeners() {
    document.getElementById('btn-save').addEventListener('click', () => this.save());
    document.getElementById('btn-undo').addEventListener('click', () => {
      this.grid.undo();
      this.updateFormulaBar();
      this.updateNameBox();
    });
    document.getElementById('btn-redo').addEventListener('click', () => {
      this.grid.redo();
      this.updateFormulaBar();
      this.updateNameBox();
    });
    document.getElementById('btn-cut').addEventListener('click', () => this.grid.cut());
    document.getElementById('btn-copy').addEventListener('click', () => this.grid.copy());
    document.getElementById('btn-paste').addEventListener('click', () => this.grid.paste());
    document.getElementById('btn-fill-down').addEventListener('click', () => {
      this.grid.fill('down');
      this.refreshCellCalculations();
      this.updateSaveStatus('unsaved');
      this.scheduleSave();
    });
    document.getElementById('btn-fill-right').addEventListener('click', () => {
      this.grid.fill('right');
      this.refreshCellCalculations();
      this.updateSaveStatus('unsaved');
      this.scheduleSave();
    });

    document.getElementById('formula-input').addEventListener('keydown', (e) => {
      if (e.key === 'Enter') {
        e.preventDefault();
        const value = e.target.value;
        this.grid.setFormulaBarValue(value);
        this.updateSaveStatus('unsaved');
        this.scheduleSave();
      }
    });

    document.getElementById('formula-input').addEventListener('input', (e) => {
      const value = e.target.value;
      if (value.startsWith('=')) {
        const suggestions = FormulaHelper.suggestFunctions(value.substring(1));
        const suggestionsEl = document.getElementById('formula-suggestions');
        if (suggestions.length > 0) {
          suggestionsEl.innerHTML = suggestions.map(s => 
            `<div class="formula-suggestion">${s}</div>`
          ).join('');
          suggestionsEl.style.display = 'block';
        } else {
          suggestionsEl.style.display = 'none';
        }
      } else {
        document.getElementById('formula-suggestions').style.display = 'none';
      }
    });

    document.getElementById('name-box').addEventListener('keydown', (e) => {
      if (e.key === 'Enter') {
        e.preventDefault();
        const value = e.target.value;
        this.grid.setNameBoxValue(value);
        this.updateFormulaBar();
      }
    });

    document.getElementById('btn-find').addEventListener('click', () => {
      document.getElementById('find-modal').style.display = 'flex';
    });

    document.getElementById('close-find').addEventListener('click', () => {
      document.getElementById('find-modal').style.display = 'none';
    });

    document.getElementById('btn-close-find').addEventListener('click', () => {
      document.getElementById('find-modal').style.display = 'none';
    });

    document.getElementById('btn-find-all').addEventListener('click', () => this.findAll());
    document.getElementById('btn-replace-next').addEventListener('click', () => this.replaceNext());
    document.getElementById('btn-replace-all').addEventListener('click', () => this.replaceAll());

    document.getElementById('btn-revisions').addEventListener('click', () => this.showRevisions());
    document.getElementById('close-revisions').addEventListener('click', () => {
      document.getElementById('revisions-modal').style.display = 'none';
    });
    document.getElementById('btn-close-revisions').addEventListener('click', () => {
      document.getElementById('revisions-modal').style.display = 'none';
    });
    document.getElementById('btn-restore-revision').addEventListener('click', () => this.restoreRevision());

    document.getElementById('close-history').addEventListener('click', () => {
      document.getElementById('history-modal').style.display = 'none';
    });
    document.getElementById('btn-close-history').addEventListener('click', () => {
      document.getElementById('history-modal').style.display = 'none';
    });

    document.addEventListener('keydown', (e) => {
      const ctrl = e.ctrlKey || e.metaKey;
      if (ctrl && e.key.toLowerCase() === 's') {
        e.preventDefault();
        this.save();
      } else if (ctrl && e.key.toLowerCase() === 'h') {
        e.preventDefault();
        document.getElementById('find-modal').style.display = 'flex';
      }
    });

    document.addEventListener('paste', (e) => {
      if (e.target === document.getElementById('formula-input')) return;
      e.preventDefault();
      const text = e.clipboardData.getData('text/plain');
      this.grid.pasteText(text);
      this.refreshCellCalculations();
      this.updateSaveStatus('unsaved');
      this.scheduleSave();
    });
  }

  findAll() {
    const text = document.getElementById('find-input').value;
    const matchCase = document.getElementById('find-match-case').checked;
    const wholeCell = document.getElementById('find-whole-cell').checked;

    this.findResults = this.grid.find(text, { matchCase, wholeCell });
    this.findCurrentIndex = 0;
    this.displayFindResults();
  }

  displayFindResults() {
    const resultsEl = document.getElementById('find-results');
    if (this.findResults.length === 0) {
      resultsEl.innerHTML = '<div>No matches found</div>';
      return;
    }

    resultsEl.innerHTML = this.findResults.map((addr, i) => 
      `<div class="find-result-item" data-index="${i}" onclick="app.selectFindResult(${i})">${addr}: ${app.grid.cells[addr]}</div>`
    ).join('');
  }

  selectFindResult(index) {
    const addr = this.findResults[index];
    this.grid.selectCell(addr);
    this.grid.scrollToCell(addr);
    this.updateFormulaBar();
    this.updateNameBox();
  }

  replaceNext() {
    if (this.findResults.length === 0) {
      alert('No matches found');
      return;
    }

    const addr = this.findResults[this.findCurrentIndex];
    const text = document.getElementById('find-input').value;
    const replacement = document.getElementById('replace-input').value;
    const matchCase = document.getElementById('find-match-case').checked;
    const wholeCell = document.getElementById('find-whole-cell').checked;

    const value = this.grid.cells[addr] || '';
    const searchValue = matchCase ? value : value.toLowerCase();
    const searchText = matchCase ? text : text.toLowerCase();

    let newValue;
    if (wholeCell) {
      newValue = searchValue === searchText ? replacement : value;
    } else {
      newValue = value.replace(
        new RegExp(text.replace(/[.*+?^${}()|[\]\\]/g, '\\$&'), matchCase ? 'g' : 'gi'),
        replacement
      );
    }

    this.grid.cells[addr] = newValue;
    this.grid.onCellChanged(addr, value, newValue);

    this.findCurrentIndex = (this.findCurrentIndex + 1) % this.findResults.length;
    const nextAddr = this.findResults[this.findCurrentIndex];
    this.grid.selectCell(nextAddr);
    this.grid.scrollToCell(nextAddr);
  }

  replaceAll() {
    const text = document.getElementById('find-input').value;
    const replacement = document.getElementById('replace-input').value;
    const matchCase = document.getElementById('find-match-case').checked;
    const wholeCell = document.getElementById('find-whole-cell').checked;

    const updates = this.grid.replace(text, replacement, { matchCase, wholeCell });

    if (Object.keys(updates).length > 0) {
      this.refreshCellCalculations();
      this.updateSaveStatus('unsaved');
      this.scheduleSave();
      alert(`Replaced ${Object.keys(updates).length} cells`);
    } else {
      alert('No matches found');
    }
  }

  async showRevisions() {
    try {
      const data = await api.getRevisions(this.workbookId);
      const modal = document.getElementById('revisions-modal');
      const listEl = document.getElementById('revisions-list');

      listEl.innerHTML = data.revisions.map(r => `
        <div class="revision-item" data-revision="${r.revision}" onclick="app.selectRevision(${r.revision})">
          <div class="revision-item-revision">Revision ${r.revision}</div>
          <div class="revision-item-date">${new Date(r.created_at).toLocaleString()}</div>
        </div>
      `).join('');

      modal.style.display = 'flex';
    } catch (error) {
      console.error('Failed to load revisions:', error);
      alert('Failed to load revisions: ' + error.message);
    }
  }

  async selectRevision(revision) {
    try {
      const data = await api.getRevision(this.workbookId, revision);
      const previewEl = document.getElementById('preview-content');

      let preview = '';
      for (const sheet of data.sheets) {
        for (const [addr, cellData] of Object.entries(sheet.cells)) {
          const value = cellData.value;
          preview += `${addr}: ${value}\n`;
        }
      }

      previewEl.textContent = preview || '(no changes)';
      document.getElementById('revision-preview').style.display = 'block';

      this.selectedRevision = {
        revision,
        data
      };
    } catch (error) {
      console.error('Failed to load revision:', error);
      alert('Failed to load revision: ' + error.message);
    }
  }

  restoreRevision() {
    if (!this.selectedRevision) return;

    const revision = this.selectedRevision;
    for (const sheet of revision.data.sheets) {
      for (const [addr, cellData] of Object.entries(sheet.cells)) {
        this.grid.cells[addr] = cellData.value;
      }
    }

    this.currentRevision = revision.revision;
    this.refreshCellCalculations();
    this.updateFormulaBar();
    this.updateNameBox();
    this.updateSaveStatus('unsaved');
    this.scheduleSave();

    document.getElementById('revisions-modal').style.display = 'none';
  }
}

